// subjects/forms/Subject/Form moved to ./subjects-meta — that's tiny, static
// metadata with no dependency on the rest of this file's multi-MB per-chapter
// content imports. Re-exported here so existing `from "@/data/content"`
// imports keep working; prefer importing directly from "@/data/subjects-meta"
// in new code (and especially anywhere that must stay out of an eagerly-
// loaded bundle, e.g. the SSR route tree) so it doesn't pull this whole file in.
export { subjects, forms, type Subject, type Form } from "./subjects-meta";

export interface Note {
  id: string;
  subjectId: string;
  form: Form;
  chapter: string;
  title: string;
  summary: string;
  keywords: string[];
  lang?: "bm" | "dlp";
}

export interface WorkedExample {
  problem: string;
  steps: string[];
  answer: string;
}

export interface MethodCard {
  methodName: string;
  steps: string[];
  result: string;
}

export interface ProblemSolvingFlow {
  scenario: string;
  understanding: string[];
  devisingPlan: string[];
  implementing: string[];
  reflection: string;
}

export interface NumberLineVisual {
  min: number;
  max: number;
  /** Values to mark with a highlighted dot, e.g. the number(s) under discussion. */
  highlight?: number[];
}

export interface FactorTreeNode {
  value: number;
  /** True for a leaf that is itself a prime factor (rendered in accent color). */
  isPrime?: boolean;
  children?: [FactorTreeNode, FactorTreeNode];
}

export interface FactorVisual {
  /** The number being decomposed, e.g. 60. */
  number: number;
  /** Prime divisors applied in order for the repeated-division ladder, e.g. [2, 2, 3, 5]. */
  ladder: number[];
  /** Factor tree decomposition of the same number, for side-by-side comparison. */
  tree: FactorTreeNode;
}

export interface ScienceNotesSubsection {
  title?: string;
  content?: string;
  bulletPoints?: string[];
  table?: {
    headers: string[];
    rows: string[][];
  };
  formula?: string;
  /** A single worked problem with numbered steps and a final answer. */
  workedExample?: WorkedExample;
  /** Side-by-side method comparison cards (e.g. the 3 ways to find HCF/LCM). */
  methodCards?: MethodCard[];
  /** 4-step Understanding / Devising a Plan / Implementing / Reflection problem-solving flow. */
  problemSolvingFlow?: ProblemSolvingFlow;
  /** A number line diagram, or labeled real-world examples used by the chapter 1 layout. */
  numberLine?:
    | NumberLineVisual
    | {
        examples: {
          value: string;
          meaning: string;
        }[];
      };
  /** Factor tree + repeated-division ladder pair for prime factorisation. */
  factorVisual?: FactorVisual;

  /** The 4-step problem-solving flow: Understanding → Devising → Implementing → Reflection. */
  problemSolving?: ProblemSolvingFlow;
}

export interface ScienceNotesSection {
  title: string;
  subsections?: ScienceNotesSubsection[];
  content?: string;
}

export interface ScienceChapter2Notes {
  quickRevision: string[];
  sections: ScienceNotesSection[];
  keyExamFacts: string[];
  keyTerms?: string[];
  chapterSummary?: string;
}

